115	/// Persist one record file in its dataset directory, creating the directory
116	/// first.
117	async fn ensure_dataset_dir(state: &AppState, name: &str) -> Result<PathBuf, Response> {
118	    let dir = state.data_dir.join(name);
119	    if let Err(e) = tokio::fs::create_dir_all(&dir).await {
120	        tracing_error(&e);
121	        return Err(error_response(
122	            StatusCode::INTERNAL_SERVER_ERROR,
123	            "internal",
124	        ));
125	    }
126	    Ok(dir)
127	}
