210	/// Format a timestamp as RFC3339 UTC with second precision, e.g.
211	/// `2006-01-02T15:04:05Z`. Civil-from-days conversion per Howard Hinnant.
212	fn format_rfc3339_utc(t: SystemTime) -> String {
213	    let secs = t
214	        .duration_since(SystemTime::UNIX_EPOCH)
215	        .map(|d| d.as_secs())
216	        .unwrap_or(0);
217	    let days = (secs / 86400) as i64;
218	    let sod = secs % 86400;
219	    let (hour, min, sec) = (sod / 3600, (sod % 3600) / 60, sod % 60);
220	
221	    let z = days + 719468;
222	    let era = if z >= 0 { z } else { z - 146096 } / 146097;
223	    let doe = (z - era * 146097) as u64; // [0, 146096]
224	    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
225	    let year = yoe as i64 + era * 400;
226	    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
227	    let mp = (5 * doy + 2) / 153; // [0, 11]
228	    let day = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
229	    let month = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
230	    let year = if month <= 2 { year + 1 } else { year };
231	
232	    format!("{year:04}-{month:02}-{day:02}T{hour:02}:{min:02}:{sec:02}Z")
233	}
