276	fn hex_val(b: u8) -> Option<u8> {
277	    match b {
278	        b'0'..=b'9' => Some(b - b'0'),
279	        b'a'..=b'f' => Some(b - b'a' + 10),
280	        b'A'..=b'F' => Some(b - b'A' + 10),
281	        _ => None,
282	    }
283	}
