314	/// Parse the query string into a key filter. Any parameter outside the
315	/// documented set (`prefix`, `gte`, `gt`, `lte`, `lt`), duplicates,
316	/// conflicting bounds, or values that are not valid key fragments
317	/// (non-empty, `[A-Za-z0-9_-]`) are rejected.
318	fn parse_key_filter(query: &str) -> Result<KeyFilter, ()> {
319	    let mut filter = KeyFilter::default();
320	    if query.is_empty() {
321	        return Ok(filter);
322	    }
323	    let mut gte: Option<String> = None;
324	    let mut gt: Option<String> = None;
325	    let mut lte: Option<String> = None;
326	    let mut lt: Option<String> = None;
327	
328	    for pair in query.split('&') {
329	        let (raw_name, raw_value) = pair.split_once('=').ok_or(())?;
330	        let name = percent_decode(raw_name)?;
331	        let value = percent_decode(raw_value)?;
332	        if !valid_identifier(&value) {
333	            return Err(());
334	        }
335	        let slot = match name.as_str() {
336	            "prefix" => &mut filter.prefix,
337	            "gte" => &mut gte,
338	            "gt" => &mut gt,
339	            "lte" => &mut lte,
340	            "lt" => &mut lt,
341	            _ => return Err(()),
342	        };
343	        if slot.is_some() {
344	            return Err(());
345	        }
346	        *slot = Some(value);
347	    }
348	
349	    if filter.prefix.is_some() && (gte.is_some() || gt.is_some() || lte.is_some() || lt.is_some()) {
350	        return Err(());
351	    }
352	    if gte.is_some() && gt.is_some() {
353	        return Err(());
354	    }
355	    if lte.is_some() && lt.is_some() {
356	        return Err(());
357	    }
358	    filter.lower = gte.map(|b| (b, true)).or_else(|| gt.map(|b| (b, false)));
359	    filter.upper = lte.map(|b| (b, true)).or_else(|| lt.map(|b| (b, false)));
360	    Ok(filter)
361	}
