363	async fn list_records(
364	    State(state): State<AppState>,
365	    PathParam(name): PathParam<String>,
366	    uri: Uri,
367	) -> Response {
368	    if !valid_identifier(&name) {
369	        return error_response(StatusCode::BAD_REQUEST, "invalid_identifier");
370	    }
371	    let filter = match parse_key_filter(uri.query().unwrap_or("")) {
372	        Ok(filter) => filter,
373	        Err(()) => return error_response(StatusCode::BAD_REQUEST, "invalid_query"),
374	    };
375	
376	    // Shared guard across the whole scan: commits rename files one by one,
377	    // so without this a list could interleave a batch in progress.
378	    let lock = dataset_lock(&name).await;
379	    let _guard = lock.read().await;
380	    let dir = state.data_dir.join(&name);
381	    let mut entries = match tokio::fs::read_dir(&dir).await {
382	        Ok(entries) => entries,
383	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
384	            return error_response(StatusCode::NOT_FOUND, "not_found");
385	        }
386	        Err(e) => {
387	            tracing_error(&e);
388	            return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
389	        }
390	    };
391	
392	    let mut records: Vec<(String, Value, SystemTime)> = Vec::new();
393	    loop {
394	        let entry = match entries.next_entry().await {
395	            Ok(Some(entry)) => entry,
396	            Ok(None) => break,
397	            Err(e) => {
398	                tracing_error(&e);
399	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
400	            }
401	        };
402	        let file_name = entry.file_name();
403	        let Some(file_name) = file_name.to_str() else {
404	            continue;
405	        };
406	        let Some(key) = file_name.strip_suffix(".json") else {
407	            continue;
408	        };
409	        // Filter on the key alone, before reading: records outside the hit
410	        // set are excluded even if their file is corrupt or unreadable.
411	        if !filter.matches(key) {
412	            continue;
413	        }
414	
415	        let result = async {
416	            let bytes = tokio::fs::read(entry.path()).await?;
417	            let modified = entry.metadata().await?.modified()?;
418	            Ok::<(Vec<u8>, SystemTime), std::io::Error>((bytes, modified))
419	        }
420	        .await;
421	        let (bytes, modified) = match result {
422	            Ok(ok) => ok,
423	            Err(e) => {
424	                tracing_error(&e);
425	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
426	            }
427	        };
428	        let value: Value = match serde_json::from_slice(&bytes) {
429	            Ok(value) => value,
430	            Err(e) => {
431	                eprintln!("corrupt record {name}/{key}: {e}");
432	                return error_response(StatusCode::INTERNAL_SERVER_ERROR, "internal");
433	            }
434	        };
435	        records.push((key.to_owned(), value, modified));
436	    }
437	
438	    // Byte-wise order on UTF-8 is Unicode code-point order.
439	    records.sort_by(|a, b| a.0.cmp(&b.0));
440	    let records: Vec<Value> = records
441	        .into_iter()
442	        .map(|(key, value, modified)| {
443	            json!({
444	                "key": key,
445	                "value": value,
446	                "updatedAt": format_rfc3339_utc(modified),
447	            })
448	        })
449	        .collect();
450	    Json(json!({ "name": name, "records": records })).into_response()
451	}
