453	// ---------------------------------------------------------------------------
454	// Batch writes
455	//
456	// A batch is staged in a sibling directory of the dataset before any record
457	// file is touched:
458	//
459	//   <data_dir>/.<name>.batch-<pid>-<n>/
460	//     MANIFEST          - JSON: dataset name, batch keys, per-key "existed"
461	//                         flag, and the batch commit time; durable before
462	//                         COMMIT so recovery never has to infer key state
463	//                         from partially moved directories
464	//     COMMIT            - present once the whole batch is durably staged
465	//     ABORT             - present once a rollback has been decided
466	//     new/<key>.json    - new payload, staged via temp file + fsync + rename
467	//     old/<key>.json    - hardlink to the pre-request file (existing keys)
468	//
469	// Records are switched into the dataset only after COMMIT is durable, and
470	// the dataset directory is fsynced once all renames are done. A crash before
471	// COMMIT leaves the dataset untouched; a crash afterwards is completed at
472	// startup (re-apply) or, if ABORT exists, rolled back. Old payloads are
473	// captured as hardlinks, so rolling back restores both content and inode
474	// metadata (notably updatedAt). MANIFEST records whether each key existed
475	// beforehand, making both resume paths idempotent regardless of where a
476	// previous attempt stopped.
477	// ---------------------------------------------------------------------------
478	
479	const COMMIT_MARKER: &str = "COMMIT";
480	const ABORT_MARKER: &str = "ABORT";
481	const MANIFEST_FILE: &str = "MANIFEST";
482	
483	/// Why a batch request was rejected.
484	#[derive(Clone, Copy, PartialEq, Eq)]
485	enum BatchError {
486	    /// Malformed JSON envelope or entries.
487	    InvalidJson,
488	    /// An entry key (already structurally present) violates identifier rules.
489	    InvalidIdentifier,
490	}
491	
492	/// Validate and parse a batch request body into `(key, value)` pairs.
493	fn parse_batch_records(body: &[u8]) -> Result<Vec<(String, Value)>, BatchError> {
494	    if body.is_empty() {
495	        return Err(BatchError::InvalidJson);
496	    }
497	    let parsed: Value = serde_json::from_slice(body).map_err(|_| BatchError::InvalidJson)?;
498	    let Some(obj) = parsed.as_object() else {
499	        return Err(BatchError::InvalidJson);
500	    };
501	    // Missing `records`, or a non-array value, is invalid_json.
502	    let Some(arr) = obj.get("records").and_then(|v| v.as_array()) else {
503	        return Err(BatchError::InvalidJson);
504	    };
505	
506	    let mut entries: Vec<(String, Value)> = Vec::with_capacity(arr.len());
507	    for item in arr {
508	        // Every entry must be an object with a string `key` and a present
509	        // `value` (which may itself be null).
510	        let Some(item) = item.as_object() else {
511	            return Err(BatchError::InvalidJson);
512	        };
513	        let Some(key) = item.get("key").and_then(|k| k.as_str()) else {
514	            return Err(BatchError::InvalidJson);
515	        };
516	        let Some(value) = item.get("value") else {
517	            return Err(BatchError::InvalidJson);
518	        };
519	        entries.push((key.to_owned(), value.clone()));
520	    }
521	
522	    // A key that violates the identifier charset is invalid_identifier.
523	    if entries.iter().any(|(key, _)| !valid_identifier(key)) {
524	        return Err(BatchError::InvalidIdentifier);
525	    }
526	
527	    // Duplicate keys within one batch are invalid_json.
528	    let mut seen = HashSet::with_capacity(entries.len());
529	    for (key, _) in &entries {
530	        if !seen.insert(key.as_str()) {
531	            return Err(BatchError::InvalidJson);
532	        }
533	    }
534	    Ok(entries)
535	}
