554	/// Staging directory for a batch: a sibling of the dataset directory.
555	fn staging_dir(state: &AppState, name: &str) -> PathBuf {
556	    state.data_dir.join(format!(
557	        ".{name}.batch-{}-{}",
558	        std::process::id(),
559	        BATCH_COUNTER.fetch_add(1, Ordering::Relaxed)
560	    ))
561	}
